  bubble=new TextView(host);bubble.setText("✦");bubble.setTextColor(0xFFFFB08A);bubble.setTextSize(25);bubble.setGravity(Gravity.CENTER);bubble.setContentDescription("Neo Agent Touch 悬浮对话，拖动可移动");bubble.setOnClickListener(v->open());bubble.setBackground(background(0xF22B2928,24,0xFFEF9D78));bubble.setElevation(dp(7));
