 private void sendDraft(){if(!owner()||screenLocked()||input==null)return;String text=input.getText().toString().trim();if(text.isEmpty())return;draft=text;handoff(()->{draft="";host.floatingConversation.submit(text);});}
 private void handoff(Runnable request){if(!owner()||screenLocked())return;beforeExecution();awaitingReply=true;handoffPending=true;final long ticket=++handoffEpoch;host.main.postDelayed(()->{if(owner()&&!screenLocked()&&ticket==handoffEpoch&&!panelVisible()){handoffPending=false;request.run();}},160);}
