 void voiceRequested(){if(!owner()||screenLocked())return;EditText target=focusInput();if(target!=null)host.floatingVoice.start(target);}
 void voiceStatus(String text){if(Looper.myLooper()!=Looper.getMainLooper()){host.main.post(()->voiceStatus(text));return;}if(!owner()||screenLocked())return;voiceHint=text==null?"":text;if(hint!=null)hint.setText(voiceHint);}
 boolean hasPanel(){return panel!=null;}
 boolean panelVisible(){return panel!=null&&panel.isAttachedToWindow();}
 void beforeExecution(){awaitingReply=false;hidePanel();}
 void hide(){awaitingReply=false;hidePanel();}
 private void hidePanel(){
  if(Looper.myLooper()!=Looper.getMainLooper()){host.main.post(this::hidePanel);return;}
  handoffEpoch++;handoffPending=false;host.floatingVoice.cancel();
  final boolean attached=panel!=null&&panel.isAttachedToWindow();
  if(input!=null){draft=input.getText().toString();if(ControlService.instance==null||ControlService.instance==host)((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);input.clearFocus();}
  if(panel!=null&&windows!=null)try{windows.removeViewImmediate(panel);}catch(RuntimeException ignored){}
  if(panel!=null&&panel.isAttachedToWindow()){voiceHint="面板尚未收起，请重试关闭；目标未开始";if(hint!=null)hint.setText(voiceHint);return;}
  panel=null;input=null;history=null;pending=null;scroller=null;status=null;hint=null;send=null;cancel=null;panelTitle="";historyKey=pendingKey="";
  if(attached&&owner()&&!screenLocked()&&host.paused&&!host.running&&host.busy())host.showOverlay();
 }
 void hideAll(){awaitingReply=false;hidePanel();if(bubble!=null&&windows!=null)try{windows.removeViewImmediate(bubble);}catch(RuntimeException ignored){}if(bubble==null||!bubble.isAttachedToWindow()){bubble=null;bubbleTitle="";avoidingEpoch=-1;}}
