 boolean owns(AccessibilityWindowInfo window){if(window.getType()!=AccessibilityWindowInfo.TYPE_ACCESSIBILITY_OVERLAY)return false;CharSequence title=window.getTitle();return title!=null&&(!bubbleTitle.isEmpty()&&bubbleTitle.contentEquals(title)||!panelTitle.isEmpty()&&panelTitle.contentEquals(title));}
