 boolean avoid(Rect path)throws Exception{if(!owner())throw new ControlService.UiChangedException();if(panelVisible())throw new ControlService.UiChangedException();Rect b=bounds();if(b==null)return false;if(!Rect.intersects(b,path))return false;android.util.DisplayMetrics display=host.screenMetrics();int[] point=FloatingChatGeometry.avoid(display.widthPixels,display.heightPixels,b.width(),b.height(),dp(18),b.left,b.top,path.left,path.top,path.right,path.bottom);if(point==null)throw new Exception("悬浮入口遮挡当前路径，请换一个可见入口");WindowManager.LayoutParams p=(WindowManager.LayoutParams)bubble.getLayoutParams();avoidingEpoch=dragEpoch;avoidX=p.x;avoidY=p.y;p.x+=point[0]-b.left;p.y+=point[1]-b.top;update(bubble,p);return true;}
