 private void update(View view,WindowManager.LayoutParams p){if(!owner())return;try{windows.updateViewLayout(view,p);}catch(RuntimeException ignored){}}
 private void adjustForControlBar(){if(bubble==null||dragging||avoidingEpoch!=-1)return;Rect own=bounds();if(own==null)return;android.util.DisplayMetrics m=host.screenMetrics();SharedPreferences prefs=host.getSharedPreferences("ui",0);int[] at=FloatingChatGeometry.position(m.widthPixels,m.heightPixels,own.width(),own.height(),dp(18),prefs.getFloat("floatingChatX",1),prefs.getFloat("floatingChatY",.5f));Rect bar=host.controlBar.bounds();if(bar!=null){Rect blocked=new Rect(bar);blocked.inset(-dp(8),-dp(8));int[] clear=FloatingChatGeometry.avoid(m.widthPixels,m.heightPixels,own.width(),own.height(),dp(18),at[0],at[1],blocked.left,blocked.top,blocked.right,blocked.bottom);if(clear!=null)at=clear;}WindowManager.LayoutParams p=(WindowManager.LayoutParams)bubble.getLayoutParams();if(p.x!=at[0]||p.y!=at[1]){p.x=at[0];p.y=at[1];update(bubble,p);}}
 private void savePosition(WindowManager.LayoutParams p){if(!owner())return;android.util.DisplayMetrics m=host.screenMetrics();float[] n=FloatingChatGeometry.normalize(m.widthPixels,m.heightPixels,p.width,p.height,dp(18),p.x,p.y);host.getSharedPreferences("ui",0).edit().putFloat("floatingChatX",n[0]).putFloat("floatingChatY",n[1]).apply();}
